// Optional report attachment shared by the record entry and book appointment forms.
// The file is uploaded as a lab report for the member; nothing is sent until the form is saved.
import 'package:file_picker/file_picker.dart';
import 'package:flutter/material.dart';

typedef ReportAttachment = ({String name, String path});

class ReportAttachmentField extends StatelessWidget {
  const ReportAttachmentField({
    required this.attachment,
    required this.onChanged,
    required this.onError,
    this.label = 'Upload medical report',
    this.enabled = true,
    super.key,
  });

  static const maxBytes = 10485760;
  static const allowedExtensions = ['pdf', 'png', 'jpg', 'jpeg'];

  final ReportAttachment? attachment;
  final ValueChanged<ReportAttachment?> onChanged;
  final ValueChanged<String> onError;
  final String label;
  final bool enabled;

  Future<void> _pick() async {
    try {
      final result = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: allowedExtensions,
      );
      final file = result?.files.single;
      final path = file?.path;
      if (file == null || path == null) return;
      if (file.size > maxBytes) {
        onError('Choose a PNG, JPEG or PDF report up to 10 MB.');
        return;
      }
      onChanged((name: file.name, path: path));
    } catch (_) {
      onError('The file could not be opened. Choose another file.');
    }
  }

  @override
  Widget build(BuildContext context) => Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      OutlinedButton.icon(
        onPressed: enabled ? _pick : null,
        icon: const Icon(Icons.attach_file),
        label: Text(attachment == null ? label : 'Change report'),
      ),
      if (attachment != null)
        Row(
          children: [
            Expanded(
              child: Text(
                attachment!.name,
                overflow: TextOverflow.ellipsis,
              ),
            ),
            IconButton(
              tooltip: 'Remove attachment',
              onPressed: enabled ? () => onChanged(null) : null,
              icon: const Icon(Icons.close),
            ),
          ],
        ),
    ],
  );
}
